import 'dart:async';import 'package:flutter/material.dart';import '../models/user.dart';import '../services/api.dart';
class Chat extends StatefulWidget{final User user;final String? directUserId,communityId,title;const Chat({super.key,required this.user,this.directUserId,this.communityId,this.title});@override State<Chat> createState()=>_ChatState();}
class _ChatState extends State<Chat>{final t=TextEditingController();List msgs=[];Timer? timer;@override void initState(){super.initState();load();timer=Timer.periodic(const Duration(seconds:3),(_)=>load());}@override void dispose(){timer?.cancel();t.dispose();super.dispose();}String get path=>widget.communityId!=null?'/chats/community/${widget.communityId}':'/chats/direct/${widget.directUserId}';Future<void>load()async{try{final r=await Api.get(path);if(mounted)setState(()=>msgs=List.from(r['messages']??[]));}catch(_){} }Future<void>send()async{if(t.text.trim().isEmpty)return;try{await Api.post(path,{'text':t.text.trim()});t.clear();load();}catch(x){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$x')));}}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.title??'Chat')),body:Column(children:[Expanded(child:ListView.builder(padding:const EdgeInsets.all(14),itemCount:msgs.length,itemBuilder:(c,i){final m=Map<String,dynamic>.from(msgs[i]);final s=m['sender'] is Map?Map<String,dynamic>.from(m['sender']):{};final mine='${s['_id']??''}'==widget.user.id;return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.only(bottom:8),padding:const EdgeInsets.symmetric(horizontal:14,vertical:10),constraints:const BoxConstraints(maxWidth:330),decoration:BoxDecoration(color:mine?Theme.of(c).colorScheme.primaryContainer:Colors.white,borderRadius:BorderRadius.circular(18)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[if(!mine)Text('${s['name']??''}',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:12)),Text('${m['text']??''}')])));})),SafeArea(child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:t,textInputAction:TextInputAction.send,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'Write a message...',filled:true))),const SizedBox(width:8),IconButton.filled(onPressed:send,icon:const Icon(Icons.send))])))]));}
